CREATE PROCEDURE [Setup_bulkinsert]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@changeTable [Setup_BulkType] READONLY
AS
BEGIN
-- use a temp table to store the list of PKs that successfully got updated/inserted
DECLARE @changed TABLE ([IDPost] tinyint, PRIMARY KEY ([IDPost]));

-- update/insert into the base table
MERGE [Setup] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [Setup_tracking] t ON p.[IDPost] = t.[IDPost]) AS changes ON changes.[IDPost] = base.[IDPost]
WHEN NOT MATCHED BY TARGET AND changes.local_update_peer_timestamp <= @sync_min_timestamp OR changes.local_update_peer_timestamp IS NULL THEN
INSERT ([IDPost], [MName], [NRep2], [NRep3], [NRep4], [NRep5], [NRep6], [NRep7], [NRep8], [NRep9], [ARep2], [ARep3], [ARep4], [ARep5], [ARep6], [ARep7], [ARep8], [ARep9], [VelDia], [TSSNum0], [TSSNum1], [TSSNum2], [TSSNum3], [TSSNum4], [TSSNum5], [TSSNum6], [TSSNum7], [TSSNum8], [TSSNum9], [Passw], [TotTick], [DataEnd], [DataIni], [NImp], [PBonus], [FPPremio], [FForza], [NomeLocale], [IndiLocale], [CittaLocale], [ProvLocale], [TelLocale], [numcommMT1], [numcommMT2], [numcommMT3], [numcommMT4], [numcommMT5], [numcommCR], [numcommBR], [numcommPR], [NConc], [NTrack], [ScoMan], [Ric25], [Pre25], [TypePrt], [SecMonX], [SecMonY], [OpRig], [Lang], [Log], [MultiUser], [CardReader], [CBarC], [NCogn], [OpResi], [VisP0], [FT24H], [NT24H], [FTNew], [PInter], [FTBDay], [FPrPr], [FPrCr], [ScPromo], [ScLun], [ScMar], [ScMer], [ScGio], [ScVen], [ScSab], [ScDom], [OraPIni], [OraPEnd], [DataPIni], [DataPEnd], [AddSP], [PrNoSc], [TmOpen], [TmClose], [OpScoMan], [AutoNT], [NTMolt], [OpCli], [MQPrem], [VisNome], [AutoConv], [TicStat], [BkDisk], [CRaw], [PercAbb], [NTAbb], [PasswSM], [MagPremLoc], [PTBon], [BTLun], [BTMar], [BTMer], [BTGio], [BTVen], [BTSab], [BTDom], [OraBIni], [OraBEnd], [DataBIni], [DataBEnd], [AbPr], [AbBt], [InvPass], [ManAdd], [OpMPremi], [OpALOff], [HideList], [HideMov], [FndCod], [NoInatt], [OpRapp], [NoOAcq], [VinPrInatt], [Inv0], [BkpOk], [Easys], [FornMan], [POMan], [MdbSaveInt], [OpAppL], [NewConc], [IniConc], [BandaMag], [RegInc], [IncDay], [LastInc], [IncIva], [CanPO], [NoAnnAPl], [ValGett], [ValTick], [NtickRic], [OrInv], [AbOrInv], [ALAggTick], [ALAggCosto], [ALAggRis], [ALAggBarc], [SaveScan], [NoCanPr], [ModCode], [IdMT1], [IdMT2], [IdMT3], [IdMT4], [IdMT5], [CIndir], [Ab4Usr], [AbBr0], [AbBr1], [AbBr2], [AbBr3], [PBRm0], [PBRm1], [PBRm2], [PBRm3], [AbMon3], [Mon3H], [Mon3V], [VBase], [ConnOk], [AdmPass], [HSMOp], [HSMMa], [Mistral], [MisCode], [MisVCard], [MisVSerie], [FtpPOrd], [MisData], [MisCard], [MisSerie], [OpModCli], [MMCosto], [MMTick], [ALAggType], [MMMSco], [EndOk], [DataStop], [AbId2], [NomeSped], [IndSped], [CittaSped], [ProvSped], [TelSped], [TRed], [TGru], [TPus], [TAlt], [NewSet], [Master], [CodEcs], [Modif], [SyncRes], [SyncEn], [NRepMT1], [NRepMT2], [NRepMT3], [NRepMT4], [NRepMT5], [F0], [F1], [F2], [F3], [F4], [F5], [F6], [F7], [T0], [T1], [T2], [T3], [T4], [T5], [T6], [T7], [N0], [N1], [N2], [N3], [N4], [N5], [N6], [N7], [D0], [D1], [D2], [D3], [D4], [D5], [D6], [D7], [F8], [F9], [F10], [F11], [F12], [F13], [F14], [F15], [T8], [T9], [T10], [T11], [T12], [T13], [T14], [T15], [N8], [N9], [N10], [N11], [N12], [N13], [N14], [N15], [D8], [D9], [D10], [D11], [D12], [D13], [D14], [D15], [GCassa], [VCassa]) VALUES (changes.[IDPost], changes.[MName], changes.[NRep2], changes.[NRep3], changes.[NRep4], changes.[NRep5], changes.[NRep6], changes.[NRep7], changes.[NRep8], changes.[NRep9], changes.[ARep2], changes.[ARep3], changes.[ARep4], changes.[ARep5], changes.[ARep6], changes.[ARep7], changes.[ARep8], changes.[ARep9], changes.[VelDia], changes.[TSSNum0], changes.[TSSNum1], changes.[TSSNum2], changes.[TSSNum3], changes.[TSSNum4], changes.[TSSNum5], changes.[TSSNum6], changes.[TSSNum7], changes.[TSSNum8], changes.[TSSNum9], changes.[Passw], changes.[TotTick], changes.[DataEnd], changes.[DataIni], changes.[NImp], changes.[PBonus], changes.[FPPremio], changes.[FForza], changes.[NomeLocale], changes.[IndiLocale], changes.[CittaLocale], changes.[ProvLocale], changes.[TelLocale], changes.[numcommMT1], changes.[numcommMT2], changes.[numcommMT3], changes.[numcommMT4], changes.[numcommMT5], changes.[numcommCR], changes.[numcommBR], changes.[numcommPR], changes.[NConc], changes.[NTrack], changes.[ScoMan], changes.[Ric25], changes.[Pre25], changes.[TypePrt], changes.[SecMonX], changes.[SecMonY], changes.[OpRig], changes.[Lang], changes.[Log], changes.[MultiUser], changes.[CardReader], changes.[CBarC], changes.[NCogn], changes.[OpResi], changes.[VisP0], changes.[FT24H], changes.[NT24H], changes.[FTNew], changes.[PInter], changes.[FTBDay], changes.[FPrPr], changes.[FPrCr], changes.[ScPromo], changes.[ScLun], changes.[ScMar], changes.[ScMer], changes.[ScGio], changes.[ScVen], changes.[ScSab], changes.[ScDom], changes.[OraPIni], changes.[OraPEnd], changes.[DataPIni], changes.[DataPEnd], changes.[AddSP], changes.[PrNoSc], changes.[TmOpen], changes.[TmClose], changes.[OpScoMan], changes.[AutoNT], changes.[NTMolt], changes.[OpCli], changes.[MQPrem], changes.[VisNome], changes.[AutoConv], changes.[TicStat], changes.[BkDisk], changes.[CRaw], changes.[PercAbb], changes.[NTAbb], changes.[PasswSM], changes.[MagPremLoc], changes.[PTBon], changes.[BTLun], changes.[BTMar], changes.[BTMer], changes.[BTGio], changes.[BTVen], changes.[BTSab], changes.[BTDom], changes.[OraBIni], changes.[OraBEnd], changes.[DataBIni], changes.[DataBEnd], changes.[AbPr], changes.[AbBt], changes.[InvPass], changes.[ManAdd], changes.[OpMPremi], changes.[OpALOff], changes.[HideList], changes.[HideMov], changes.[FndCod], changes.[NoInatt], changes.[OpRapp], changes.[NoOAcq], changes.[VinPrInatt], changes.[Inv0], changes.[BkpOk], changes.[Easys], changes.[FornMan], changes.[POMan], changes.[MdbSaveInt], changes.[OpAppL], changes.[NewConc], changes.[IniConc], changes.[BandaMag], changes.[RegInc], changes.[IncDay], changes.[LastInc], changes.[IncIva], changes.[CanPO], changes.[NoAnnAPl], changes.[ValGett], changes.[ValTick], changes.[NtickRic], changes.[OrInv], changes.[AbOrInv], changes.[ALAggTick], changes.[ALAggCosto], changes.[ALAggRis], changes.[ALAggBarc], changes.[SaveScan], changes.[NoCanPr], changes.[ModCode], changes.[IdMT1], changes.[IdMT2], changes.[IdMT3], changes.[IdMT4], changes.[IdMT5], changes.[CIndir], changes.[Ab4Usr], changes.[AbBr0], changes.[AbBr1], changes.[AbBr2], changes.[AbBr3], changes.[PBRm0], changes.[PBRm1], changes.[PBRm2], changes.[PBRm3], changes.[AbMon3], changes.[Mon3H], changes.[Mon3V], changes.[VBase], changes.[ConnOk], changes.[AdmPass], changes.[HSMOp], changes.[HSMMa], changes.[Mistral], changes.[MisCode], changes.[MisVCard], changes.[MisVSerie], changes.[FtpPOrd], changes.[MisData], changes.[MisCard], changes.[MisSerie], changes.[OpModCli], changes.[MMCosto], changes.[MMTick], changes.[ALAggType], changes.[MMMSco], changes.[EndOk], changes.[DataStop], changes.[AbId2], changes.[NomeSped], changes.[IndSped], changes.[CittaSped], changes.[ProvSped], changes.[TelSped], changes.[TRed], changes.[TGru], changes.[TPus], changes.[TAlt], changes.[NewSet], changes.[Master], changes.[CodEcs], changes.[Modif], changes.[SyncRes], changes.[SyncEn], changes.[NRepMT1], changes.[NRepMT2], changes.[NRepMT3], changes.[NRepMT4], changes.[NRepMT5], changes.[F0], changes.[F1], changes.[F2], changes.[F3], changes.[F4], changes.[F5], changes.[F6], changes.[F7], changes.[T0], changes.[T1], changes.[T2], changes.[T3], changes.[T4], changes.[T5], changes.[T6], changes.[T7], changes.[N0], changes.[N1], changes.[N2], changes.[N3], changes.[N4], changes.[N5], changes.[N6], changes.[N7], changes.[D0], changes.[D1], changes.[D2], changes.[D3], changes.[D4], changes.[D5], changes.[D6], changes.[D7], changes.[F8], changes.[F9], changes.[F10], changes.[F11], changes.[F12], changes.[F13], changes.[F14], changes.[F15], changes.[T8], changes.[T9], changes.[T10], changes.[T11], changes.[T12], changes.[T13], changes.[T14], changes.[T15], changes.[N8], changes.[N9], changes.[N10], changes.[N11], changes.[N12], changes.[N13], changes.[N14], changes.[N15], changes.[D8], changes.[D9], changes.[D10], changes.[D11], changes.[D12], changes.[D13], changes.[D14], changes.[D15], changes.[GCassa], changes.[VCassa])
OUTPUT INSERTED.[IDPost] INTO @changed; -- populates the temp table with successful PKs

UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0,
create_scope_local_id = @sync_scope_local_id,
scope_create_peer_key = changes.sync_create_peer_key,
scope_create_peer_timestamp = changes.sync_create_peer_timestamp,
local_create_peer_key = 0
FROM 
[Setup_tracking] side JOIN 
(SELECT p.[IDPost], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[IDPost] = t.[IDPost]) AS changes ON changes.[IDPost] = side.[IDPost]
SELECT [IDPost] FROM @changeTable t WHERE NOT EXISTS (SELECT [IDPost] from @changed i WHERE t.[IDPost] = i.[IDPost])
END
